ring = SortedMap()
for cache in site.caches:
    for v in range(100):
        ring[hash(f"{cache.id}#{v}")] = cache

def caches_for(file_id, k):
    h = hash(file_id); out = []
    for node in ring.walk_from(h):
        if node not in out and node.healthy: out.append(node)
        if len(out) == k: break
    return out

