def run_workflow(asset):
    ladder = LadderBuilder.analyze(asset)
    chunks = split_at_scene_cuts(asset.master, target_s=180)
    tasks = [(c, r) for c in chunks for r in ladder]
    parallel_for(tasks, max_parallel=500, retries=3, backoff='exp_jitter',
                 fn=lambda c, r: ChunkEncoder.encode(c, r))
    for r in ladder:
        out = concat([key(asset, c, r) for c in chunks])
        if vmaf(out) < r.min_vmaf or not av_sync_ok(out): raise QCFailed(r)
    package_and_encrypt(asset, ladder)
